insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('cuanto-cuesta-un-dia-tipico-en-tu-ciudad','negocios',array['ciudades','sociedad']::text[],'¿Cuánto cuesta un día típico en tu ciudad?','Calcula cuánto cuesta vivir un día completo en tu ciudad, desde el transporte y la comida hasta una salida, y compáralo con otra forma de pasar el día.','Análisis','~15 h',15,array['Costo de vida','Ciudad']::text[],array['investigar']::text[],'propios',NULL,'economia administracion sociologia geografia estadistica contabilidad comunicaciones ingenieria industrial observacion de precios. calculo de costos. analisis comparativo. comunicacion clara. hoja de calculo. cuaderno de registro de precios. un editor de graficos.',$a14sld${"id": "cuanto-cuesta-un-dia-tipico-en-tu-ciudad", "area": "negocios", "areas2": ["ciudades", "sociedad"], "titulo": "¿Cuánto cuesta un día típico en tu ciudad?", "resumen": "Calcula cuánto cuesta vivir un día completo en tu ciudad, desde el transporte y la comida hasta una salida, y compáralo con otra forma de pasar el día.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Costo de vida", "Ciudad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Sociología", "Geografía", "Estadística", "Contabilidad", "Comunicaciones", "Ingeniería Industrial"], "problema": ["Cada ciudad tiene su propio costo cotidiano, que se nota en el pasaje, el almuerzo o una salida, pero casi nadie lo suma. Por eso es difícil comparar, por ejemplo, un día de estudio con uno de paseo, o una zona con otra.", "Convertir un día en cifras ayuda a entender cuánto pesa cada tipo de gasto y por qué ciertas actividades se vuelven inalcanzables para algunas personas."], "desarrollar": ["Diseña tres días típicos distintos, como uno de clases, uno de trabajo y uno de salida con amigos, y calcula cuánto costaría cada uno con precios reales que anotes en tu zona.", "Presenta los tres costos en una tabla y un gráfico, destaca qué actividades pesan más y propón dos alternativas más económicas para cada día."], "ampliaciones": [{"titulo": "Otra zona", "aporta": "compara el costo del mismo día en otro barrio o ciudad."}, {"titulo": "Costo para quien tiene menos", "aporta": "adapta los días a un presupuesto muy ajustado."}, {"titulo": "Día ideal", "aporta": "diseña un día agradable al menor costo posible."}], "objetivos": ["Definir días típicos con criterio.", "Anotar precios reales con fecha.", "Calcular y comparar costos.", "Proponer alternativas."], "habilidades": ["Observación de precios.", "Cálculo de costos.", "Análisis comparativo.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Cuaderno de registro de precios.", "Un editor de gráficos."], "lineamientos": ["Registra solo precios públicos, sin nombres de personas ni datos privados, y fecha cada dato.", "No uses el análisis para juzgar estilos de vida: es una descripción de costos."], "otroSector": "El mismo ejercicio sirve para estimar cuánto cuesta un día de producción, de rodaje, de un evento o de una jornada de trabajo."}$a14sld$::jsonb,22),
('el-impacto-de-las-compras-impulsivas','negocios',array['sociedad']::text[],'El impacto de las compras impulsivas','Descubre qué compras haces sin planificar, qué las provoca y cuánto dinero representan, y prueba una pequeña estrategia para decidir mejor.','Investigación','~20 h',20,array['Consumo','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'psicologia economia administracion comunicaciones publicidad sociologia contabilidad estadistica autoobservacion y registro. analisis de habitos. diseno de pruebas simples. reflexion critica. hoja de calculo o libreta. un editor de graficos. un formulario anonimo, si comparas con otros.',$a15sld${"id": "el-impacto-de-las-compras-impulsivas", "area": "negocios", "areas2": ["sociedad"], "titulo": "El impacto de las compras impulsivas", "resumen": "Descubre qué compras haces sin planificar, qué las provoca y cuánto dinero representan, y prueba una pequeña estrategia para decidir mejor.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Consumo", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Psicología", "Economía", "Administración", "Comunicaciones", "Publicidad", "Sociología", "Contabilidad", "Estadística"], "problema": ["Una compra impulsiva ocurre cuando se decide en el momento, por una oferta, un anuncio, el cansancio o la emoción. Se siente bien al comprar, pero a veces se lamenta después.", "Entender qué situaciones la activan permite diseñar maneras de decidir con más calma, sin quitarle gusto a comprar."], "desarrollar": ["Durante dos semanas anota cada compra y marca si estaba planeada o no, qué la provocó y cómo te sentiste después, sin juzgarte.", "Suma el monto de lo no planeado, busca patrones y prueba una regla sencilla, como esperar un tiempo antes de comprar, durante otra semana. Compara y concluye qué te funcionó."], "ampliaciones": [{"titulo": "Anuncios y estímulos", "aporta": "analiza qué tipo de publicidad o de oferta te llevó a comprar más."}, {"titulo": "Lo que no se lamenta", "aporta": "identifica qué compras no planeadas sí valieron la pena."}, {"titulo": "Comparar con otros", "aporta": "compara de manera anónima con compañeros qué activa sus compras."}], "objetivos": ["Registrar compras y su origen.", "Reconocer patrones.", "Probar una estrategia simple.", "Concluir con honestidad."], "habilidades": ["Autoobservación y registro.", "Análisis de hábitos.", "Diseño de pruebas simples.", "Reflexión crítica."], "herramientas": ["Hoja de cálculo o libreta.", "Un editor de gráficos.", "Un formulario anónimo, si comparas con otros."], "lineamientos": ["Trabaja con tus propias compras y no con las de otras personas; si comparas, hazlo de forma anónima y voluntaria.", "No es un diagnóstico de conductas: si sientes que gastas de forma que te perjudica, conversa con alguien de confianza o un profesional."], "otroSector": "El mismo método sirve para estudiar decisiones rápidas en otros ámbitos, como clics, inscripciones o suscripciones."}$a15sld$::jsonb,23),
('cuando-suben-los-precios-basicos-el-presupuesto-de-una-familia','negocios',array['sociedad']::text[],'Cuando suben los precios básicos: el presupuesto de una familia','Simula cómo cambia el presupuesto de una familia inventada cuando suben los precios de la comida, el transporte o los servicios, y qué decisiones tendría que tomar.','Simulación','~22 h',22,array['Precios','Hogar']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'economia estadistica contabilidad administracion sociologia trabajo social ingenieria industrial ciencia de datos modelado en hoja de calculo. analisis de escenarios. lectura de datos de precios. comunicacion de resultados. hoja de calculo. precios de referencia de fuentes publicas. un editor de graficos.',$a16sld${"id": "cuando-suben-los-precios-basicos-el-presupuesto-de-una-familia", "area": "negocios", "areas2": ["sociedad"], "titulo": "Cuando suben los precios básicos: el presupuesto de una familia", "resumen": "Simula cómo cambia el presupuesto de una familia inventada cuando suben los precios de la comida, el transporte o los servicios, y qué decisiones tendría que tomar.", "tipo": "Simulación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Precios", "Hogar"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Estadística", "Contabilidad", "Administración", "Sociología", "Trabajo Social", "Ingeniería Industrial", "Ciencia de Datos"], "problema": ["Cuando suben los precios de lo básico, los hogares no solo pagan más: tienen que decidir qué recortar, qué cambiar por algo más barato y qué postergar. No todas las familias lo viven igual, porque depende de cuánto de su ingreso se va en lo esencial.", "Las noticias hablan de porcentajes de inflación, pero rara vez se traducen a lo que ocurre en un presupuesto real."], "desarrollar": ["Inventa dos familias con distintos ingresos y arma el presupuesto mensual de cada una, con alimentos, transporte, servicios, educación y otros gastos, usando precios de referencia públicos.", "Simula un aumento de precios en tres rubros, calcula cuánto sube el gasto en cada familia, qué porcentaje del ingreso representa y qué ajustes tendría que hacer, y compara los resultados."], "ampliaciones": [{"titulo": "Con datos públicos", "aporta": "usa un índice de precios para ver cuánto subieron realmente los productos básicos en un año."}, {"titulo": "Diferentes hogares", "aporta": "añade un hogar con gastos de salud o de cuidado y compara el efecto."}, {"titulo": "Respuestas posibles", "aporta": "propón y compara tres estrategias para ajustarse a los precios más altos."}], "objetivos": ["Construir presupuestos realistas con casos ficticios.", "Aplicar cambios de precios con criterio.", "Comparar el efecto entre hogares.", "Explicar las decisiones posibles."], "habilidades": ["Modelado en hoja de cálculo.", "Análisis de escenarios.", "Lectura de datos de precios.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Precios de referencia de fuentes públicas.", "Un editor de gráficos."], "lineamientos": ["Trabaja con familias inventadas y precios públicos; no uses datos de familias reales ni ejemplos que identifiquen a alguien.", "Evita presentar el resultado como una predicción: es una simulación para entender el efecto."], "otroSector": "La misma simulación sirve para estudiar el efecto de un aumento de costos en un negocio, un colegio o una organización."}$a16sld$::jsonb,24),
('simula-la-economia-de-un-hogar-durante-un-mes','negocios',array['sociedad','educacion']::text[],'Simula la economía de un hogar durante un mes','Crea el mes económico de una familia ficticia, con ingresos, gastos, imprevistos y un plan de ahorro, y observa cómo sus decisiones afectan su resultado.','Simulación','~25 h',25,array['Hogar','Simulación']::text[],array['crear','investigar']::text[],'ficticios',NULL,'economia contabilidad administracion educacion ingenieria de sistemas estadistica ingenieria industrial trabajo social modelado y simulacion. registro de decisiones. analisis de resultados. diseno de planes. hoja de calculo. dados o una tabla de eventos aleatorios. herramientas de programacion, si quieres automatizarla.',$a17sld${"id": "simula-la-economia-de-un-hogar-durante-un-mes", "area": "negocios", "areas2": ["sociedad", "educacion"], "titulo": "Simula la economía de un hogar durante un mes", "resumen": "Crea el mes económico de una familia ficticia, con ingresos, gastos, imprevistos y un plan de ahorro, y observa cómo sus decisiones afectan su resultado.", "tipo": "Simulación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Hogar", "Simulación"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Educación", "Ingeniería de Sistemas", "Estadística", "Ingeniería Industrial", "Trabajo Social"], "problema": ["La economía de un hogar es un sistema de ingresos y gastos que cambia cada semana: llegan pagos, aparecen imprevistos y se toman decisiones sobre qué comprar. Entenderlo con un caso real es difícil porque implicaría datos privados.", "Un caso ficticio bien armado permite practicar sin riesgo y aprender cómo pequeñas decisiones, como cuándo comprar o qué pagar primero, cambian el resultado del mes."], "desarrollar": ["Inventa una familia con integrantes, ingresos y gastos fijos, y define reglas para eventos del mes, como un gasto imprevisto, un ingreso extra o una oferta tentadora.", "Simula el mes semana por semana, registra las decisiones y su efecto en un tablero, y propón un plan de ahorro realista para la familia, comprobando si se cumple en la simulación."], "ampliaciones": [{"titulo": "Juego de roles", "aporta": "propón que varias personas tomen decisiones por la familia y compara resultados."}, {"titulo": "Meses encadenados", "aporta": "continúa la simulación varios meses y observa cómo se acumulan los efectos."}, {"titulo": "Versión interactiva", "aporta": "convierte la simulación en una hoja o página donde se elijan decisiones y se vea el resultado."}], "objetivos": ["Construir un caso ficticio coherente.", "Definir reglas de eventos y decisiones.", "Simular y registrar resultados.", "Diseñar un plan de ahorro y evaluarlo."], "habilidades": ["Modelado y simulación.", "Registro de decisiones.", "Análisis de resultados.", "Diseño de planes."], "herramientas": ["Hoja de cálculo.", "Dados o una tabla de eventos aleatorios.", "Herramientas de programación, si quieres automatizarla."], "lineamientos": ["Inventa los datos de la familia sin basarte en personas reales y no incluyas información financiera verdadera.", "Aclara que es un juego de aprendizaje y no un modelo exacto de cómo funcionan todos los hogares."], "otroSector": "La misma simulación sirve para entrenar decisiones en una pequeña empresa, una organización estudiantil o un proyecto con recursos limitados."}$a17sld$::jsonb,25),
('cuanto-ahorra-un-hogar-al-planificar-sus-compras','negocios',array['sociedad','agricultura']::text[],'¿Cuánto ahorra un hogar al planificar sus compras?','Compara el gasto de un mes con compras planificadas frente a compras sin lista y descubre cuánto dinero y desperdicio puede evitar una buena organización.','Análisis','~20 h',20,array['Compras','Planificación']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia administracion ingenieria industrial contabilidad nutricion estadistica ingenieria agroindustrial educacion registro de datos. analisis comparativo. planificacion. comunicacion clara. hoja de calculo. boletas o notas de compra. una plantilla de lista de compras.',$a18sld${"id": "cuanto-ahorra-un-hogar-al-planificar-sus-compras", "area": "negocios", "areas2": ["sociedad", "agricultura"], "titulo": "¿Cuánto ahorra un hogar al planificar sus compras?", "resumen": "Compara el gasto de un mes con compras planificadas frente a compras sin lista y descubre cuánto dinero y desperdicio puede evitar una buena organización.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Compras", "Planificación"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Ingeniería Industrial", "Contabilidad", "Nutrición", "Estadística", "Ingeniería Agroindustrial", "Educación"], "problema": ["Hacer las compras sin plan lleva a comprar de más, repetir productos o dejar que se echen a perder. Pero casi nadie mide cuánto dinero se pierde así, y la planificación suele verse como una molestia.", "Medir la diferencia con datos propios permite saber si planificar realmente compensa el esfuerzo."], "desarrollar": ["Durante un mes anota lo que gastas en compras del hogar sin plan, y durante otro haz una lista semanal con lo que necesitas y un presupuesto, anotando lo comprado y lo que se desperdicia.", "Compara los dos meses en gasto total, en cantidad de productos que sobraron y en tiempo invertido, y concluye si planificar vale la pena en tu caso."], "ampliaciones": [{"titulo": "Tamaño del hogar", "aporta": "analiza cómo cambia el resultado según cuántas personas viven en casa."}, {"titulo": "Lista inteligente", "aporta": "diseña una plantilla de lista de compras que ayude a no olvidar ni repetir."}, {"titulo": "Ofertas y planificación", "aporta": "compara cuánto ahorra aprovechar ofertas con y sin plan."}], "objetivos": ["Medir el gasto en compras con método.", "Comparar dos formas de comprar.", "Calcular el ahorro y el desperdicio.", "Presentar conclusiones honestas."], "habilidades": ["Registro de datos.", "Análisis comparativo.", "Planificación.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Boletas o notas de compra.", "Una plantilla de lista de compras."], "lineamientos": ["Si compartes los resultados, oculta nombres, direcciones y otros datos de las boletas; usa solo montos y productos.", "Presenta los resultados como una experiencia de un mes y no como un promedio para todos."], "otroSector": "El mismo análisis sirve para evaluar la planificación de compras de insumos en un negocio, un colegio o una cocina."}$a18sld$::jsonb,26),
('conviene-comprar-en-presentaciones-grandes-o-individuales','negocios',array['sociedad']::text[],'¿Conviene comprar en presentaciones grandes o individuales?','Calcula el precio por unidad de varios productos en presentaciones pequeñas, medianas y familiares, y descubre cuándo la grande realmente conviene.','Análisis','~15 h',15,array['Precios','Compras']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia administracion contabilidad estadistica ingenieria industrial matematica nutricion educacion calculo de precios unitarios. observacion de datos. analisis comparativo. comunicacion clara. hoja de calculo. cuaderno para anotar precios en tiendas. un editor de graficos.',$a19sld${"id": "conviene-comprar-en-presentaciones-grandes-o-individuales", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Conviene comprar en presentaciones grandes o individuales?", "resumen": "Calcula el precio por unidad de varios productos en presentaciones pequeñas, medianas y familiares, y descubre cuándo la grande realmente conviene.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Precios", "Compras"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Estadística", "Ingeniería Industrial", "Matemática", "Nutrición", "Educación"], "problema": ["Se asume que la presentación grande es siempre más barata, pero no siempre es así: a veces cuesta casi lo mismo por unidad, otras veces se desperdicia por no consumirla a tiempo, y otras conviene mucho.", "El precio por unidad no siempre está visible, y comparar presentaciones distintas exige hacer cuentas que casi nadie hace en la tienda."], "desarrollar": ["Elige diez productos de consumo común, anota el precio y el contenido de cada presentación disponible, y calcula el precio por unidad de medida para cada una.", "Identifica en cuáles la presentación grande ahorra mucho, poco o nada, considera si se consumiría antes de vencer o de malograrse y arma una regla práctica para decidir."], "ampliaciones": [{"titulo": "Cuándo se desperdicia", "aporta": "agrega el costo de lo que no se llega a usar."}, {"titulo": "Distintos tipos de tienda", "aporta": "compara si cambia el resultado según el tipo de tienda."}, {"titulo": "Regla rápida", "aporta": "crea una tarjeta simple para decidir en la tienda sin calculadora."}], "objetivos": ["Reunir precios y contenidos con orden.", "Calcular precios por unidad.", "Comparar presentaciones.", "Formular una regla práctica."], "habilidades": ["Cálculo de precios unitarios.", "Observación de datos.", "Análisis comparativo.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Cuaderno para anotar precios en tiendas.", "Un editor de gráficos."], "lineamientos": ["Anota precios públicos con su fecha y evita fotografiar a personas dentro de tiendas; no recomiendes marcas ni tiendas específicas.", "Considera que lo más barato por unidad no siempre es lo mejor si no se puede almacenar o consumir a tiempo."], "otroSector": "El mismo análisis de precio por unidad sirve para insumos de un negocio, para servicios por horas o por paquetes, y para planes de datos."}$a19sld$::jsonb,27),
('el-costo-de-oportunidad-en-la-vida-cotidiana','negocios',array['sociedad','educacion']::text[],'El costo de oportunidad en la vida cotidiana','Descubre cómo cada decisión cotidiana implica renunciar a otra opción, y practica reconocer qué se pierde y qué se gana al elegir.','Investigación','~15 h',15,array['Economía','Decisiones']::text[],array['investigar','otro-sector']::text[],'ficticios',NULL,'economia administracion psicologia filosofia educacion estadistica contabilidad ingenieria industrial pensamiento economico. analisis de alternativas. argumentacion. comunicacion clara. hoja de calculo o tabla. casos inventados. un editor de presentaciones.',$a20sld${"id": "el-costo-de-oportunidad-en-la-vida-cotidiana", "area": "negocios", "areas2": ["sociedad", "educacion"], "titulo": "El costo de oportunidad en la vida cotidiana", "resumen": "Descubre cómo cada decisión cotidiana implica renunciar a otra opción, y practica reconocer qué se pierde y qué se gana al elegir.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Economía", "Decisiones"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Administración", "Psicología", "Filosofía", "Educación", "Estadística", "Contabilidad", "Ingeniería Industrial"], "problema": ["Cada vez que se elige algo, se deja de elegir otra cosa: una tarde de estudio es una tarde que no se trabaja, y un gasto es dinero que no se ahorra. A ese valor de lo que se renuncia se le llama costo de oportunidad.", "Casi nunca se piensa así, y por eso se toman decisiones que parecen gratis cuando no lo son. Hacerlo visible ayuda a decidir mejor."], "desarrollar": ["Elige cinco decisiones cotidianas, como estudiar o trabajar, comprar o ahorrar, ir a una actividad o descansar, y para cada una describe cuál era la mejor alternativa que se dejó y qué valor tendría.", "Presenta cada caso en una ficha o tabla simple y explica en qué situaciones el costo de oportunidad cambia la decisión."], "ampliaciones": [{"titulo": "Un caso con números", "aporta": "convierte uno de los casos en un cálculo con tiempo y dinero."}, {"titulo": "Decisiones de otros", "aporta": "analiza las decisiones de un personaje ficticio y qué costo de oportunidad enfrentó."}, {"titulo": "Tarjeta de decisión", "aporta": "crea una tarjeta con tres preguntas para pensar antes de decidir."}], "objetivos": ["Comprender el concepto de costo de oportunidad.", "Aplicarlo a decisiones cotidianas.", "Comparar alternativas con criterio.", "Explicarlo a otras personas con claridad."], "habilidades": ["Pensamiento económico.", "Análisis de alternativas.", "Argumentación.", "Comunicación clara."], "herramientas": ["Hoja de cálculo o tabla.", "Casos inventados.", "Un editor de presentaciones."], "lineamientos": ["Usa casos inventados o decisiones propias que quieras compartir; no juzgues las decisiones de nadie.", "Recuerda que no todo se puede medir en dinero, y que la mejor alternativa para una persona no lo es para otra."], "otroSector": "El mismo concepto sirve para decidir cómo asignar el tiempo de un equipo, los recursos de un proyecto o el presupuesto de una organización."}$a20sld$::jsonb,28),
('decisiones-economicas-con-informacion-limitada','negocios',array['sociedad','ciencias']::text[],'Decisiones económicas con información limitada','Estudia cómo decidir bien cuando no tienes toda la información, qué factores pesan y cómo evitar los errores más comunes al elegir.','Investigación','~20 h',20,array['Decisiones','Incertidumbre']::text[],array['investigar','otro-sector']::text[],'ficticios',NULL,'economia estadistica administracion psicologia ingenieria industrial matematica ciencia de datos contabilidad analisis de decisiones. pensamiento probabilistico basico. comparacion de escenarios. argumentacion. hoja de calculo o tabla. casos inventados. un editor de diagramas de decision.',$a21sld${"id": "decisiones-economicas-con-informacion-limitada", "area": "negocios", "areas2": ["sociedad", "ciencias"], "titulo": "Decisiones económicas con información limitada", "resumen": "Estudia cómo decidir bien cuando no tienes toda la información, qué factores pesan y cómo evitar los errores más comunes al elegir.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Decisiones", "Incertidumbre"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Estadística", "Administración", "Psicología", "Ingeniería Industrial", "Matemática", "Ciencia de Datos", "Contabilidad"], "problema": ["Casi todas las decisiones económicas se toman sin saber todo: no se conocen los precios del futuro, ni las intenciones del otro, ni todos los costos ocultos. Aun así hay que decidir.", "Entender qué factores influyen, desde el precio hasta las emociones, y qué errores son frecuentes, ayuda a decidir con más criterio sin esperar certeza total."], "desarrollar": ["Elige tres decisiones, como comprar un producto, aceptar un trabajo o iniciar un negocio, y para cada una lista qué información tienes, cuál falta, qué factores pesan y qué riesgos hay.", "Aplica un método sencillo, como comparar escenarios optimista, normal y pesimista, y concluye cómo decidirías y qué información intentarías obtener primero."], "ampliaciones": [{"titulo": "Sesgos frecuentes", "aporta": "identifica qué errores de juicio podrían influir en cada decisión."}, {"titulo": "Valor de la información", "aporta": "estima cuánto valdría conseguir un dato antes de decidir."}, {"titulo": "Decidir en grupo", "aporta": "compara cómo cambia la decisión si la toma un grupo."}], "objetivos": ["Reconocer qué información falta.", "Comparar escenarios.", "Identificar factores y errores comunes.", "Justificar una decisión con criterio."], "habilidades": ["Análisis de decisiones.", "Pensamiento probabilístico básico.", "Comparación de escenarios.", "Argumentación."], "herramientas": ["Hoja de cálculo o tabla.", "Casos inventados.", "Un editor de diagramas de decisión."], "lineamientos": ["Usa casos inventados y presenta tu método como una forma de pensar, no como una fórmula infalible.", "No lo uses para tomar decisiones importantes de dinero o de salud sin consultar a un profesional."], "otroSector": "La misma forma de decidir sirve en medicina, en ingeniería, en política pública o en cualquier decisión de un equipo."}$a21sld$::jsonb,29),
('crea-una-idea-de-negocio-con-baja-inversion','negocios',array['sociedad']::text[],'Crea una idea de negocio con baja inversión','Diseña una idea de negocio que pueda empezar con muy poco dinero, define qué problema resuelve, a quién le sirve y cómo se probaría antes de invertir más.','Plan','~20 h',20,array['Emprendimiento','Idea de negocio']::text[],array['crear','resolver']::text[],'ficticios',NULL,'administracion economia ingenieria industrial contabilidad comunicaciones marketing ingenieria de sistemas diseno pensamiento emprendedor. estimacion de costos. diseno de pruebas simples. comunicacion clara. hoja de calculo. un lienzo de modelo de negocio. precios de mercado.',$a22sld${"id": "crea-una-idea-de-negocio-con-baja-inversion", "area": "negocios", "areas2": ["sociedad"], "titulo": "Crea una idea de negocio con baja inversión", "resumen": "Diseña una idea de negocio que pueda empezar con muy poco dinero, define qué problema resuelve, a quién le sirve y cómo se probaría antes de invertir más.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Emprendimiento", "Idea de negocio"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Administración", "Economía", "Ingeniería Industrial", "Contabilidad", "Comunicaciones", "Marketing", "Ingeniería de Sistemas", "Diseño"], "problema": ["Muchas buenas ideas no arrancan porque se piensa que hace falta mucho capital. Pero hay negocios que pueden probarse con muy poca inversión si se empieza pequeño, se usa lo que ya se tiene y se valida antes de gastar.", "El reto está en elegir una idea que resuelva una necesidad real y en poder explicar con números cuánto costaría empezar."], "desarrollar": ["Elige un problema o una necesidad que veas a tu alrededor y propón un producto o servicio sencillo que lo resuelva, describiendo qué ofreces, a quién y por qué lo preferirían.", "Lista lo mínimo necesario para empezar, estima el costo inicial con precios que investigues, define una prueba pequeña, como vender a diez personas, y qué resultado indicaría que vale la pena seguir."], "ampliaciones": [{"titulo": "Tres ideas comparadas", "aporta": "propón tres ideas y compáralas por inversión, riesgo y facilidad."}, {"titulo": "Plan de prueba", "aporta": "diseña una prueba de dos semanas con metas claras."}, {"titulo": "Plan de crecimiento", "aporta": "describe qué harías si la prueba funciona."}], "objetivos": ["Identificar una necesidad real.", "Definir una oferta sencilla.", "Estimar la inversión mínima.", "Diseñar una prueba de validación."], "habilidades": ["Pensamiento emprendedor.", "Estimación de costos.", "Diseño de pruebas simples.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Un lienzo de modelo de negocio.", "Precios de mercado."], "lineamientos": ["Trabaja con una idea propia o ficticia y no uses datos privados de negocios reales ni de clientes.", "Es un ejercicio de aprendizaje: no inviertas dinero real basándote solo en esta estimación."], "otroSector": "El mismo método sirve para probar un producto digital, una actividad de una organización estudiantil o un servicio dentro de una empresa."}$a22sld$::jsonb,30),
('disena-un-modelo-de-negocio-para-un-producto-hecho-por-estudiant','negocios',array['educacion']::text[],'Diseña un modelo de negocio para un producto hecho por estudiantes','Elige un producto que podrían fabricar o crear estudiantes y diseña cómo ganaría dinero: a quién se lo venden, cómo lo entregan, qué cuesta y cuánto dejaría.','Plan','~22 h',22,array['Modelo de negocio','Estudiantes']::text[],array['crear']::text[],'ficticios',NULL,'administracion economia ingenieria industrial marketing contabilidad diseno ingenieria de sistemas comunicaciones diseno de modelos de negocio. estimacion financiera. analisis critico. trabajo en equipo. un lienzo de modelo de negocio. hoja de calculo. un editor de presentaciones.',$a23sld${"id": "disena-un-modelo-de-negocio-para-un-producto-hecho-por-estudiant", "area": "negocios", "areas2": ["educacion"], "titulo": "Diseña un modelo de negocio para un producto hecho por estudiantes", "resumen": "Elige un producto que podrían fabricar o crear estudiantes y diseña cómo ganaría dinero: a quién se lo venden, cómo lo entregan, qué cuesta y cuánto dejaría.", "tipo": "Plan", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Modelo de negocio", "Estudiantes"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Administración", "Economía", "Ingeniería Industrial", "Marketing", "Contabilidad", "Diseño", "Ingeniería de Sistemas", "Comunicaciones"], "problema": ["Un producto hecho por estudiantes, como artesanías, apuntes, accesorios o postres, puede ser un pequeño negocio, pero solo si se piensa cómo se produce, se vende y se cobra, y si deja ganancia después de contar los costos y el tiempo.", "Un modelo de negocio ordena esas decisiones en una sola vista y permite detectar qué falla antes de producir."], "desarrollar": ["Inventa un producto y describe con un lienzo de modelo de negocio sus clientes, propuesta de valor, canales de venta, fuentes de ingreso, costos principales y recursos necesarios.", "Estima cuántas unidades se venderían al mes, calcula costos y ganancia, y señala los dos puntos más débiles del modelo con una mejora para cada uno."], "ampliaciones": [{"titulo": "Tres modelos posibles", "aporta": "compara vender por encargo, en feria y por internet."}, {"titulo": "Costo del tiempo", "aporta": "incluye cuánto vale el tiempo del equipo estudiante."}, {"titulo": "Escala", "aporta": "analiza qué cambiaría si se vendiera diez veces más."}], "objetivos": ["Describir el modelo con un lienzo.", "Estimar ingresos y costos.", "Identificar debilidades.", "Proponer mejoras."], "habilidades": ["Diseño de modelos de negocio.", "Estimación financiera.", "Análisis crítico.", "Trabajo en equipo."], "herramientas": ["Un lienzo de modelo de negocio.", "Hoja de cálculo.", "Un editor de presentaciones."], "lineamientos": ["Trabaja con un producto inventado; si usas uno real, que sea tuyo o con permiso de sus autores.", "Considera las normas de higiene y seguridad si el producto es de consumo."], "otroSector": "El mismo modelo sirve para un servicio de la universidad, un club o una pequeña empresa de tecnología."}$a23sld$::jsonb,31),
('quien-es-el-cliente-de-tu-emprendimiento-perfil-de-cliente-ideal','negocios',array['sociedad']::text[],'¿Quién es el cliente de tu emprendimiento? Perfil de cliente ideal','Define con quién quieres trabajar: describe a tu cliente ideal con base en entrevistas breves y observación, y adapta tu oferta a lo que realmente necesita.','Investigación','~18 h',18,array['Cliente','Marketing']::text[],array['investigar','crear']::text[],'propios',NULL,'marketing administracion psicologia sociologia comunicaciones estadistica economia diseno entrevista y escucha. analisis cualitativo. sintesis de informacion. comunicacion clara. guion de preguntas. hoja de calculo o tabla. un editor de presentaciones.',$a24sld${"id": "quien-es-el-cliente-de-tu-emprendimiento-perfil-de-cliente-ideal", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Quién es el cliente de tu emprendimiento? Perfil de cliente ideal", "resumen": "Define con quién quieres trabajar: describe a tu cliente ideal con base en entrevistas breves y observación, y adapta tu oferta a lo que realmente necesita.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Cliente", "Marketing"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Marketing", "Administración", "Psicología", "Sociología", "Comunicaciones", "Estadística", "Economía", "Diseño"], "problema": ["Muchos emprendimientos dicen venderle «a todos», y terminan sin llegarle a nadie. Cuando no se sabe quién es el cliente, el mensaje, el precio y el canal se eligen a ciegas.", "Conocer a un cliente concreto, qué le preocupa, dónde compra y qué pagaría, orienta todas las decisiones siguientes."], "desarrollar": ["Elige un emprendimiento real o inventado y haz entrevistas cortas de cinco a diez personas que podrían ser sus clientes, con preguntas sobre qué necesitan, cómo lo resuelven hoy y qué les molesta.", "Con las respuestas arma uno o dos perfiles de cliente, con rasgos, necesidades y frustraciones, y propón qué cambiarías en la oferta para ellos."], "ampliaciones": [{"titulo": "Mapa de empatía", "aporta": "completa un mapa de empatía con lo que piensan, ven y sienten."}, {"titulo": "Clientes que no son", "aporta": "describe a quién no le servirías y por qué."}, {"titulo": "Mensaje por perfil", "aporta": "escribe un mensaje de venta distinto para cada perfil."}], "objetivos": ["Planificar entrevistas breves.", "Identificar necesidades reales.", "Construir perfiles de cliente.", "Adaptar la oferta."], "habilidades": ["Entrevista y escucha.", "Análisis cualitativo.", "Síntesis de información.", "Comunicación clara."], "herramientas": ["Guion de preguntas.", "Hoja de cálculo o tabla.", "Un editor de presentaciones."], "lineamientos": ["Pide permiso antes de entrevistar, explica para qué usarás las respuestas y no guardes nombres ni datos de contacto.", "Presenta los perfiles como resúmenes y no como retratos de personas reales."], "otroSector": "El mismo método sirve para conocer a usuarios de una aplicación, a estudiantes de un curso o a vecinos de una comunidad."}$a24sld$::jsonb,32),
('disena-una-propuesta-de-valor-para-un-emprendimiento','negocios',array['sociedad']::text[],'Diseña una propuesta de valor para un emprendimiento','Explica con claridad por qué alguien elegiría tu producto o servicio en lugar de otro, y comprueba si tu propuesta se entiende en una sola frase.','Plan','~15 h',15,array['Propuesta de valor','Emprendimiento']::text[],array['crear']::text[],'ficticios',NULL,'marketing administracion comunicaciones diseno economia psicologia ingenieria industrial ingenieria de sistemas redaccion clara. analisis de diferenciacion. pruebas con usuarios. pensamiento critico. un lienzo de propuesta de valor. tarjetas o papelitos. un formulario sencillo.',$a25sld${"id": "disena-una-propuesta-de-valor-para-un-emprendimiento", "area": "negocios", "areas2": ["sociedad"], "titulo": "Diseña una propuesta de valor para un emprendimiento", "resumen": "Explica con claridad por qué alguien elegiría tu producto o servicio en lugar de otro, y comprueba si tu propuesta se entiende en una sola frase.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Propuesta de valor", "Emprendimiento"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Administración", "Comunicaciones", "Diseño", "Economía", "Psicología", "Ingeniería Industrial", "Ingeniería de Sistemas"], "problema": ["Una propuesta de valor responde qué ganas al elegir este producto y no otro. Muchos negocios la dan por supuesta y terminan describiendo características en lugar de beneficios.", "Si el cliente no la entiende rápido, compara solo por precio, y ahí es difícil ganar."], "desarrollar": ["Para un emprendimiento real o inventado, lista los problemas que resuelve, los beneficios que da y lo que lo diferencia de las alternativas, y redáctalo en una frase clara.", "Prueba la frase con cinco personas, anota qué entendieron y qué dudas tuvieron, y mejora hasta que se entienda sin explicación extra."], "ampliaciones": [{"titulo": "Tres versiones de la frase", "aporta": "escribe tres versiones y averigua cuál se entiende mejor."}, {"titulo": "Frente a la competencia", "aporta": "compara tu propuesta con la de dos competidores."}, {"titulo": "Del mensaje al producto", "aporta": "revisa si el producto realmente cumple lo que promete."}], "objetivos": ["Distinguir características de beneficios.", "Redactar una propuesta clara.", "Probarla con personas.", "Mejorarla con la respuesta recibida."], "habilidades": ["Redacción clara.", "Análisis de diferenciación.", "Pruebas con usuarios.", "Pensamiento crítico."], "herramientas": ["Un lienzo de propuesta de valor.", "Tarjetas o papelitos.", "Un formulario sencillo."], "lineamientos": ["No prometas beneficios que el producto no pueda cumplir y evita comparaciones que perjudiquen injustamente a otros.", "Pide permiso a quienes prueben tu frase y no registres sus datos personales."], "otroSector": "El mismo ejercicio sirve para presentar un proyecto, un portafolio personal o una propuesta de investigación."}$a25sld$::jsonb,33),
('calcula-el-punto-de-equilibrio-de-un-pequeno-negocio','negocios',array['industria']::text[],'Calcula el punto de equilibrio de un pequeño negocio','Averigua cuántas unidades tiene que vender un negocio pequeño para no perder dinero, separando costos fijos y variables, y simula qué pasa si cambian los precios o los costos.','Análisis','~20 h',20,array['Punto de equilibrio','Costos']::text[],array['resolver','investigar']::text[],'ficticios',NULL,'contabilidad economia administracion ingenieria industrial estadistica matematica ingenieria de sistemas finanzas analisis de costos. calculo en hoja de calculo. graficos de ingresos y costos. interpretacion de resultados. hoja de calculo. un editor de graficos. datos inventados.',$a26sld${"id": "calcula-el-punto-de-equilibrio-de-un-pequeno-negocio", "area": "negocios", "areas2": ["industria"], "titulo": "Calcula el punto de equilibrio de un pequeño negocio", "resumen": "Averigua cuántas unidades tiene que vender un negocio pequeño para no perder dinero, separando costos fijos y variables, y simula qué pasa si cambian los precios o los costos.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Punto de equilibrio", "Costos"], "intencion": ["resolver", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Contabilidad", "Economía", "Administración", "Ingeniería Industrial", "Estadística", "Matemática", "Ingeniería de Sistemas", "Finanzas"], "problema": ["Un negocio puede estar lleno de clientes y aun así perder dinero si los ingresos no cubren los costos. El punto de equilibrio indica cuánto hay que vender para empezar a ganar.", "Muchos emprendedores lo calculan mal o no lo calculan, y tienen que adivinar si les conviene seguir."], "desarrollar": ["Inventa un negocio pequeño, como una venta de comida o un servicio, con precios, costos fijos, como alquiler o servicios, y costos variables por unidad.", "Calcula el punto de equilibrio en unidades y en soles, grafica ingresos y costos, y simula qué ocurre si sube el costo de un insumo o si baja el precio, explicando cada resultado."], "ampliaciones": [{"titulo": "Varios productos", "aporta": "calcula el punto de equilibrio cuando el negocio vende más de un producto."}, {"titulo": "Meta de ganancia", "aporta": "calcula cuánto vender para ganar una cantidad deseada."}, {"titulo": "Margen de seguridad", "aporta": "mide cuánto pueden caer las ventas antes de perder dinero."}], "objetivos": ["Distinguir costos fijos y variables.", "Calcular el punto de equilibrio.", "Graficar la situación.", "Analizar cambios en precios y costos."], "habilidades": ["Análisis de costos.", "Cálculo en hoja de cálculo.", "Gráficos de ingresos y costos.", "Interpretación de resultados."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa datos inventados, no datos reales de negocios que no sean tuyos.", "Indica que los costos del modelo son supuestos y que en un negocio real habría que verificarlos."], "otroSector": "El mismo cálculo sirve para evaluar un evento, un taller, un producto digital o una campaña."}$a26sld$::jsonb,34)
